// pool created with { max: 20 }  (no connectionTimeoutMillis set)
async function runQuery(sql, params) {
  let conn;
  for (let attempt = 0; attempt < 5; attempt++) {
    try {
      conn = await pool.acquire();        // wait for a free connection
      const rows = await conn.query(sql, params);
      pool.release(conn);
      return rows;
    } catch (err) {
      // acquire or query failed — try again
    }
  }
  throw new Error('runQuery failed');
}
